// MÉDECIN-CHEF IA v1 — la page Santé passe par sante_cmo.php, qui transmet l'authentification du site : on la compare
// à FINANCE_USER / FINANCE_PASS. Sans elle, refus (sinon n'importe qui pourrait écrire dans le dossier par ce webhook).
const j = $input.first().json, h = j.headers || {};
let attendu = '';
try { const u = $env.FINANCE_USER, p = $env.FINANCE_PASS; if (u && p) attendu = 'Basic ' + Buffer.from(u + ':' + p).toString('base64'); } catch (e) { /* $env indisponible */ }
const recu = String(h.authorization || h.Authorization || '');
return [{ json: Object.assign({}, j, { autorise: !!attendu && recu === attendu }) }];

// MÉDECIN-CHEF IA v1 — LA QUESTION, quel que soit le canal : Telegram (texte ou vocal transcrit), page web, autre workflow
const j = $input.first().json;
const fait = (n) => { try { return $(n).isExecuted; } catch (e) { return false; } };
let question = '', canal = 'telegram', voix = false, chatId = null;
if (fait('Webhook page web')) { canal = 'web'; question = (j.body && j.body.question) || j.question || ''; }
else if (fait('When Executed by Another Workflow')) { canal = 'workflow'; question = j.query || ''; }
else {
  const m = $('Telegram Trigger').first().json.message || {};
  chatId = m.chat ? m.chat.id : null; voix = !!m.voice;
  question = voix ? (j.text || '') : (m.text || m.caption || '');
}
//  mêmes sessions de mémoire qu'avant : le chat Telegram, et « charif_master_session » pour l'agent maître
const session = canal === 'web' ? 'sante-web' : canal === 'workflow' ? 'charif_master_session' : String(chatId);
return [{ json: { question: String(question).slice(0, 6000), canal, voix, chat_id: chatId, session_id: session,
  entree: (voix ? '[VOCAL] ' : '') + (canal === 'web' ? '[PAGE SANTÉ] ' : '') + String(question).slice(0, 6000) } }];

// MÉDECIN-CHEF IA v1 — OUTIL sante_lire : le dossier tel que le moteur le calcule (GET sante_api.php?lecture=1)
// ── authentification Caddy (basic_auth sur /finance/) : identifiants dans les variables d'environnement de n8n
//    (FINANCE_USER, FINANCE_PASS, N8N_BLOCK_ENV_ACCESS_IN_NODE=false — voir N8N_AUTH_CADDY.md), JAMAIS dans le code.
let authHeader = '';
try { const u = $env.FINANCE_USER, p = $env.FINANCE_PASS; if (u && p) authHeader = 'Basic ' + Buffer.from(u + ':' + p).toString('base64'); } catch (e) { /* $env indisponible */ }
const authHeaders = authHeader ? { Authorization: authHeader } : {};
const BASE = '__FINANCE_BASE__/finance/sante/sante_api.php';
const echec = (e, quoi) => {
  const statut = (e && (e.statusCode || e.status || (e.response && e.response.statusCode))) || null;
  let corps = (e && e.response && e.response.body) || null;
  if (typeof corps === 'string') { try { corps = JSON.parse(corps); } catch (_) { /* brut */ } }
  return JSON.stringify({ erreur: quoi + ' impossible', statut, reponse_serveur: corps, detail: String((e && e.message) || e).slice(0, 300),
    conseil: statut === 401 ? 'FINANCE_USER / FINANCE_PASS absents ou faux dans n8n (N8N_AUTH_CADDY.md)' : undefined });
};

let input = {};
try { input = typeof query === 'string' ? (query.trim().startsWith('{') ? JSON.parse(query) : { date: query.trim() }) : (query || {}); } catch (e) { input = {}; }
const date = /^\d{4}-\d{2}-\d{2}$/.test(String(input.date || '')) ? String(input.date) : '';
try {
  const r = await this.helpers.httpRequest({ method: 'GET', url: BASE + '?lecture=1' + (date ? '&date=' + date : ''), headers: { ...authHeaders }, json: true, timeout: 20000 });
  return JSON.stringify(r);
} catch (e) { return echec(e, 'lecture du dossier'); }

