    conseil: statut === 401 ? 'FINANCE_USER / FINANCE_PASS absents ou faux dans n8n (N8N_AUTH_CADDY.md)' : undefined });
};

let input = {};
try { input = typeof query === 'string' ? JSON.parse(query) : (query || {}); } catch (e) { input = {}; }
const calls = Array.isArray(input.calls) ? input.calls : (Array.isArray(input) ? input : null);
if (!calls || !calls.length) return JSON.stringify({ erreur: 'Paramètre « calls » manquant ou vide.', format_attendu: { calls: [{ function: '<fonction du catalogue>', args: {} }] } });
try {
  const r = await this.helpers.httpRequest({ method: 'POST', url: BASE, body: { calls, mode: 'simulate' }, headers: { ...authHeaders }, json: true, timeout: 25000 });
  return JSON.stringify(r);
} catch (e) { return echec(e, 'simulation'); }

